/// Pasteboard types that mark a copy as private: the nspasteboard.org types and older app-specific ones.
/// Password managers set them so that clipboard tools leave a secret alone.
public enum ClipboardPolicy {
    /// The marker types, matched exactly.
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    /// True when the copy carries any marker, so Dogear must not read it.
    public static func ignores(_ types: [String]) -> Bool {
        types.contains(where: privateTypes.contains)
    }
}
